from lxml import html as _html
from cssselect import HTMLTranslator


class PyQuery(list):
    """Minimal verification stub - NOT the real implementation."""

    def __init__(self, context=None, **kwargs):
        if isinstance(context, str):
            list.__init__(self, [_html.fromstring(context)])
        elif isinstance(context, (list, tuple)):
            list.__init__(self, context)
        else:
            list.__init__(self)

    def __call__(self, selector):
        path = HTMLTranslator().css_to_xpath(selector)
        out = []
        for el in self:
            out.extend(el.xpath(path))
        return PyQuery(out)

    def text(self):
        return ''.join(''.join(el.itertext()) for el in self)
